// Supabase Edge Function — fix-invoice-item-casing
//
// ONE-OFF historical cleanup: a bunch of already-generated Zoho invoices
// have line items whose name only differs from the real Zoho catalog item
// by casing (e.g. "Kiwi Green" vs Zoho's actual "Kiwi green"). Because
// generate-invoice never sends item_id on create (see its own comments),
// Zoho falls back to matching by exact, case-sensitive name — a casing
// mismatch means Zoho silently creates an UNLINKED free-text line instead
// of linking the real inventory item. Price was always right (that lookup
// is case-insensitive), but these lines don't count toward the real item's
// stock/sales reports in Zoho. This function re-links each one after the
// fact by re-fetching the invoice, correcting the mismatched line(s) to the
// exact Zoho name AND item_id, and leaving everything else (rate, qty,
// description, tax, totals) untouched.
//
// CORRECTIONS below was generated once from a side-by-side audit of a Zoho
// Item export and Invoice export (Jul 30 - Aug 4 2026) — every entry here
// is a specific {invoice, wrong name -> right name/item_id} pair already
// confirmed to have the correct price. Not a general-purpose matcher.
//
// Input:  { dryRun?: boolean (default true), offset?: number, limit?: number }
// Output: { processed, updated, skipped, errors, needsReview, nextOffset, results: [...] }
//
// dryRun (default true!) only fetches+diffs, never writes to Zoho — always
// run with dryRun:true first and read the results before calling again with
// dryRun:false. offset/limit page through CORRECTIONS (223 invoices) in
// batches so one invocation doesn't run into the edge function time limit or
// Zoho's own API rate limit; nextOffset in the response tells you where to
// resume, null once every invoice's been processed.
//
// Every one of these invoices is already Sent/Open (not a draft), so the
// actual PUT includes a top-level "reason" string — Zoho's API rejects an
// update to a non-draft invoice without one (error 110701).
//
// Each write is verified against what Zoho actually saved, not just that
// the request succeeded — the request explicitly resends the original
// quantity/rate for every line (only name/item_id change), but Zoho's own
// UI is known to silently reset quantity to 1 when you re-pick an item on
// a line, so this checks the returned invoice's total and each corrected
// line's quantity/rate against their pre-edit values. Flagging drift after
// the fact still leaves the invoice sitting wrong in Zoho until someone
// reads the log, so if anything drifted, one immediate follow-up write
// forces quantity/rate back to the pre-edit values and re-verifies:
//   - drift, then fixed by the follow-up  -> 'updated_auto_corrected' (counted in `updated`)
//   - drift, follow-up couldn't fix it    -> 'updated_needs_review' (counted in `needsReview`, a human needs to look at that invoice in Zoho directly)
// Only one follow-up attempt, never a retry loop — if Zoho is genuinely
// resetting these server-side, hammering it won't help.
//
// Required env vars:
//   SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
//   ZOHO_CLIENT_ID, ZOHO_CLIENT_SECRET, ZOHO_REFRESH_TOKEN, ZOHO_ORGANIZATION_ID

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

function env(key: string) {
  const val = Deno.env.get(key);
  if (!val) throw new Error(`Missing env: ${key}`);
  return val;
}

const CORS = {
  'Access-Control-Allow-Origin':  '*',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
};

async function requireAuth(req: Request): Promise<void> {
  const jwt = (req.headers.get('Authorization') || '').replace(/^Bearer\s+/i, '').trim();
  if (!jwt) throw new Error('Not authenticated');
  const res = await fetch(`${env('SUPABASE_URL')}/auth/v1/user`, {
    headers: { Authorization: `Bearer ${jwt}`, apikey: env('SUPABASE_SERVICE_ROLE_KEY') },
  });
  if (!res.ok) throw new Error('Not authenticated');
}

// Shared Zoho OAuth token cache (see migration 046) — same pattern as
// generate-invoice/cancel-order/download-invoice, so this doesn't burn
// through Zoho's refresh-token rate limit on its own.
let cachedToken = '';
let tokenExpiry = 0;
async function getZohoToken(supabase: ReturnType<typeof createClient>): Promise<string> {
  if (cachedToken && Date.now() < tokenExpiry - 60_000) return cachedToken;
  const { data: row } = await supabase
    .from('zoho_token_cache').select('access_token,expires_at').eq('id', 1).maybeSingle();
  if (row && new Date(row.expires_at).getTime() > Date.now() + 60_000) {
    cachedToken = row.access_token;
    tokenExpiry = new Date(row.expires_at).getTime();
    return cachedToken;
  }
  const res = await fetch('https://accounts.zoho.in/oauth/v2/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type:    'refresh_token',
      client_id:     env('ZOHO_CLIENT_ID'),
      client_secret: env('ZOHO_CLIENT_SECRET'),
      refresh_token: env('ZOHO_REFRESH_TOKEN'),
    }),
  });
  const data = await res.json();
  if (!data.access_token) throw new Error(`Zoho OAuth failed: ${JSON.stringify(data)}`);
  cachedToken = data.access_token;
  tokenExpiry = Date.now() + (data.expires_in ?? 3600) * 1000;
  await supabase.from('zoho_token_cache').upsert({
    id: 1, access_token: cachedToken, expires_at: new Date(tokenExpiry).toISOString(),
  });
  return cachedToken;
}

function zohoUrl(path: string, orgId: string): string {
  const sep = path.includes('?') ? '&' : '?';
  return `https://www.zohoapis.in/books/v3${path}${sep}organization_id=${orgId}`;
}

const sleep = (ms: number) => new Promise(r => setTimeout(r, ms));

